    "TEST_Analytics_Profile_2": {
        "class": "Tenant",
        "Application": {
            "class": "Application",
            "test.item-foo.0123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890123456789012345678901234": {
                "class": "Analytics_Profile",
                "remark": "description",
                "collectedStatsInternalLogging": false,
                "collectedStatsExternalLogging": true,
                "capturedTrafficInternalLogging": true,
                "capturedTrafficExternalLogging": true,
                "externalLoggingPublisher": {
                    "use": "logPub"
                },
                "notificationBySyslog": true,
                "notificationBySnmp": true,
                "notificationByEmail": true,
                "notificationEmailAddresses": [
                    "example@example.com"
                ],
                "publishIruleStatistics": true,
                "collectMaxTpsAndThroughput": true,
                "collectPageLoadTime": true,
                "collectClientSideStatistics": true,
                "collectUserSession": true,
                "collectUrl": true,
                "urlsForStatCollection": [
                    "www.example.com"
                ],
                "collectGeo": true,
                "countriesForStatCollection": [
                    "Austria"
                ],
                "collectIp": true,
                "collectSubnet": true,
                "subnetsForStatCollection": [
                    "255.255.255.0"
                ],
                "collectResponseCode": false,
                "collectUserAgent": true,
                "collectMethod": false,
                "collectOsAndBrowser": false,
                "sessionCookieSecurity": "always-secure",
                "sessionTimeoutMinutes": 15,
                "captureFilter": {
                    "requestCapturedParts": "body",
                    "responseCapturedParts": "all",
                    "dosActivity": "mitigated-by-dosl7",
                    "capturedProtocols": "http",
                    "capturedReadyForJsInjection": "enabled",
                    "nodeAddresses": [
                        "198.19.192.59",
                        "198.19.192.60"
                    ],
                    "virtualServers": [
                        "serviceMain-1-"
                    ],
                    "responseCodes": [
                        400,
                        401,
                        402
                    ],
                    "methods": [
                        "GET",
                        "POST",
                        "PUT"
                    ],
                    "urlFilterType": "white-list",
                    "urlPathPrefixes": [
                        "a.org",
                        "b.org",
                        "c.org"
                    ],
                    "userAgentSubstrings": [
                        "Mozilla (01",
                        "Mozilla (02",
                        "Mozilla (03"
                    ],
                    "clientIps": [
                        "10.9.10.10",
                        "10.9.10.11",
                        "10.9.10.12"
                    ]
                }
            },
            "logPub": {
                "class": "Log_Publisher",
                "destinations": [
                    {
                        "use": "logDest"
                    }
                ]
            },
            "logDest": {
                "class": "Log_Destination",
                "type": "remote-syslog",
                "remoteHighSpeedLog": {
                    "use": "highSpeedLog"
                }
            },
            "highSpeedLog": {
                "class": "Log_Destination",
                "type": "remote-high-speed-log",
                "pool": {
                    "use": "thePool"
                }
            },
            "thePool": {
                "class": "Pool"
            },
            "serviceMain": {
                "class": "Service_Generic",
                "virtualAddresses": [
                    "198.19.192.19",
                    "198.19.192.20",
                    "198.19.192.21"
                ],
                "virtualPort": 80,
                "profileAnalytics": {
                    "use": "pA_Sample"
                },
                "pool": "poolRoundRobin"
            },
            "poolRoundRobin": {
                "class": "Pool",
                "loadBalancingMode": "round-robin",
                "monitors": [
                    "http"
                ],
                "members": [
                    {
                        "servicePort": 80,
                        "serverAddresses": [
                            "198.19.192.58",
                            "198.19.192.59",
                            "198.19.192.60"
                        ]
                    }
                ]
            }
        }
    },
